"use client";

import {
  useEffect,
  useState,
  type ComponentType,
  type MouseEvent,
} from "react";
import { useSpring } from "motion/react";
import { AlertCircle, Check } from "lucide-react";
import { cn } from "@/lib/utils";
import Button, {
  type ButtonVariants,
} from "@/components/ui/progress-button-utils/button";
import IconSwap from "@/components/ui/progress-button-utils/icon-swap";
import TextMorph from "@/components/ui/progress-button-utils/text-morph";
import {
  amountVariants,
  progressFillVariants,
  progressOutcomeText,
} from "@/components/ui/progress-button-utils/progress-button-variants";

export type ProgressButtonState = "idle" | "working" | "done" | "error";

export interface ProgressButtonProps {
  label: string;
  /** Shown while working, followed by the amount when there is one. */
  workingLabel: string;
  doneLabel: string;
  errorLabel?: string;
  icon?: ComponentType<{ className?: string }>;
  /** 0 to 100 while working. Without it, the label shimmers instead. */
  progress?: number;
  variant?: ButtonVariants["variant"];
  size?: ButtonVariants["size"];
  className?: string;
  /** The button's current phase. Uncontrolled by default (starts at `idle`); pass `state` and
   *  `onStateChange` to drive it from outside, the way Vue's `v-model:state` does. */
  state?: ProgressButtonState;
  onStateChange?: (state: ProgressButtonState) => void;
  onClick?: (event: MouseEvent<HTMLButtonElement>) => void;
}

function prefersReducedMotion() {
  return (
    typeof window !== "undefined" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );
}

// Long enough to read the result, short enough to act again soon after.
const RESULT_SHOWN = 2000;

/**
 * A button that becomes its own progress: pressed, it turns into "Exporting 40%" with the amount
 * filling it from behind, then into "Exported" with a check, and back to itself a moment later.
 * Its label morphs from phase to phase (TextMorph) and its icon turns into the next one; the
 * amount itself just updates. The work happens where it was asked for, with nothing appearing
 * elsewhere.
 *
 * Ported from elastic-ui's ProgressButton.vue (Vue + motion-v) by its original author, José
 * Estevez. Pass `state`/`onStateChange` the way you would `v-model:state`: set it to `working`
 * when the work starts and to `done` or `error` when it ends; it goes back to `idle` by itself.
 */
export default function ProgressButton({
  label,
  workingLabel,
  doneLabel,
  errorLabel = "Something went wrong",
  icon,
  progress,
  variant = "outline",
  size,
  className,
  state: controlledState,
  onStateChange,
  onClick,
}: ProgressButtonProps) {
  const [internalState, setInternalState] =
    useState<ProgressButtonState>("idle");
  const state = controlledState ?? internalState;
  const setState = (next: ProgressButtonState) => {
    if (controlledState === undefined) setInternalState(next);
    onStateChange?.(next);
  };

  // Pressable only at rest: a second press mid-work would start it again. It is not marked
  // disabled, which would dim it just as it shows its progress.
  function press(event: MouseEvent<HTMLButtonElement>) {
    if (state === "idle") onClick?.(event);
  }

  // Goes back to idle by itself once a result has been shown for a moment.
  useEffect(() => {
    if (state !== "done" && state !== "error") return;
    const back = setTimeout(() => setState("idle"), RESULT_SHOWN);
    return () => clearTimeout(back);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state]);

  const working = state === "working";
  const outcome = state === "done" || state === "error" ? state : undefined;
  const amount =
    progress === undefined
      ? undefined
      : Math.round(Math.min(100, Math.max(0, progress)));

  // The fill and the amount follow the work on a spring, which keeps its speed from one update to
  // the next, so steady steps run together into one movement (as Progress; a tween restarted on
  // each update moves in jerks). Either outcome fills the button with its colour, so it reads as a
  // result at a glance. A new start begins from empty rather than drawing back.
  const follow = useSpring(0, { stiffness: 22, damping: 12 });
  const [shown, setShown] = useState(0);
  useEffect(() => follow.on("change", setShown), [follow]);
  useEffect(() => {
    const target = outcome ? 1 : (amount ?? 0) / 100;
    if (target < shown || prefersReducedMotion()) follow.jump(target);
    else follow.set(target);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [amount, outcome]);

  const fillScale = shown;
  const shownAmount = state === "done" ? 100 : Math.round(shown * 100);
  // On a solid button the label keeps its own colour: the outcome's would not read on the fill.
  const outcomeText =
    outcome && variant !== "solid" ? progressOutcomeText[outcome] : undefined;

  // Only the phase morphs (Export → Exporting → Exported). The amount changes all the time, and a
  // morph on every tick would be noise, so it counts up beside it, in digits of one width.
  const phase =
    state === "working"
      ? amount === undefined
        ? `${workingLabel}…`
        : workingLabel
      : state === "done"
        ? doneLabel
        : state === "error"
          ? errorLabel
          : label;
  const ShownIcon =
    state === "done" ? Check : state === "error" ? AlertCircle : icon;
  const fillVisible = Boolean(outcome) || (working && amount !== undefined);

  return (
    <Button
      variant={variant}
      size={size}
      aria-busy={working || undefined}
      className={cn("relative overflow-hidden", outcomeText, className)}
      onClick={press}
    >
      {/* The fill becomes the outcome, and fades only once the button is back at rest. Work that
          had no amount to show fills in at once as it ends. */}
      <span
        aria-hidden="true"
        className={cn(
          "pointer-events-none absolute inset-0 transition-opacity duration-300",
          fillVisible ? "opacity-100" : "opacity-0",
        )}
      >
        <span
          className={progressFillVariants({ outcome: outcome ?? "none" })}
          style={{ scale: `${fillScale} 1` }}
        />
      </span>
      {/* With no amount to show, the label shimmers while it works, as everything in the library
          says it is working. */}
      <span
        className={cn(
          "relative inline-flex items-center gap-2",
          working && amount === undefined && "shimmer",
        )}
      >
        {ShownIcon && <IconSwap icon={ShownIcon} />}
        <TextMorph text={phase} />
      </span>
      {/* Room for "100%" while working, so the button keeps its width as the amount climbs. It
          unfolds as the work starts and folds away as it ends. Always there when there is an
          amount to show, so it can fold while showing where it ended. */}
      {progress !== undefined && (
        <span
          aria-hidden={!working || undefined}
          className={amountVariants({ shown: working })}
        >
          {shownAmount}%
        </span>
      )}
    </Button>
  );
}

