"use client";

import * as React from "react";
import * as Icons from "lucide-react";
import ProgressButton, {
  type ProgressButtonState,
} from "@/components/ui/progress-button";

/** Export turns into its own progress, then into "Exported", and back. */
export default function ProgressButtonDemo() {
  const [state, setState] = React.useState<ProgressButtonState>("idle");
  const [progress, setProgress] = React.useState(0);
  const timer = React.useRef<ReturnType<typeof setInterval>>();

  const start = () => {
    setState("working");
    setProgress(0);
    let current = 0;
    timer.current = setInterval(() => {
      current = Math.min(100, current + 9);
      setProgress(current);
      if (current === 100) {
        clearInterval(timer.current);
        setState("done");
      }
    }, 250);
  };

  React.useEffect(() => () => clearInterval(timer.current), []);

  return (
    <ProgressButton
      state={state}
      onStateChange={setState}
      progress={progress}
      icon={Icons.Download}
      label="Export"
      workingLabel="Exporting"
      doneLabel="Exported"
      onClick={start}
    />
  );
}

